    copied: string;
    close: string;
  };
  form: {
    editTitle: string;
    newTitle: string;
    systemId: string;
    abort: string;
    save: string;
    dragDrop: {
      analyzing: string;
      analyzingSub: string;
      title: string;
      desc: string;
    };
    sections: {
      core: string;
      vars: string;
      engineering: string;
    };
    labels: {
      designation: string;
      category: string;
      engine: string;
      persona: string;
      variables: string;
      tags: string;
      objective: string;
      inputFormat: string;
      content: string;
      notes: string;
    };
    buttons: {
      audio: string;
      audioPlaying: string;
      optimize: string;
      optimizing: string;
      add: string;
    };
    placeholders: {
      name: string;
      persona: string;
      variable: string;
      tag: string;
      objective: string;
