// Componente para Celdas tipo Excel que se expanden al hacer hover
const ExcelCell = ({ 
  content, 
  displayContent, 
  className = "",
  onClick
}: { 
  content: string, 
  displayContent?: React.ReactNode, 
  className?: string,
  onClick?: () => void
}) => {
  return (
    <div 
      onClick={onClick}
      // CAMBIO IMPORTANTE: Usamos 'group/cell' en lugar de solo 'group'
      // Esto aísla el evento hover solo a esta celda específica, ignorando la fila completa
      className={`relative group/cell h-full w-full px-3 py-2 cursor-cell hover:bg-[#1e293b] transition-colors ${className}`}
    >
      {/* Vista Compacta (Por defecto) */}
      <div className="truncate text-xs font-mono text-slate-300 h-full flex items-center select-none">
        {displayContent || content}
      </div>

      {/* Vista Expandida (Hover Pop-out) */}
      {content && (
        // CAMBIO IMPORTANTE: Usamos 'group-hover/cell:block' 
        // Añadimos 'delay-75' para evitar parpadeos al mover el ratón rápido
        <div className="hidden group-hover/cell:block absolute top-[-4px] left-[-4px] z-50 bg-[#0B1120] border border-cyan-500 shadow-[0_0_20px_rgba(6,182,212,0.4)] p-3 min-w-[calc(100%+8px)] w-max max-w-[350px] whitespace-pre-wrap break-words rounded-lg text-xs text-cyan-50 leading-relaxed animate-in fade-in zoom-in-95 duration-100 delay-75">
