        <div className="flex flex-col items-center gap-4 py-8">
           <div className={`w-24 h-24 rounded-full flex items-center justify-center border-4 ${isConnected ? 'border-green-500 animate-pulse bg-green-500/10' : 'border-slate-700 bg-slate-800'}`}>
              <Radio size={40} className={isConnected ? 'text-green-400' : 'text-slate-500'} />
           </div>
           <h3 className="text-xl font-bold text-white text-center">
             {isConnected ? 'Escuchando...' : 'Conectando...'}
           </h3>
           <p className="text-sm text-slate-400 text-center max-w-xs">
             Habla con tu prompt en tiempo real para probar su personalidad.
           </p>
