      setIsPlayingAudio(false);
    }
  };

  const handleTranscribe = async () => {
    setIsRecording(true);
    try {
      const text = await transcribeAudio();
      const newContent = (formData.content ? formData.content + "\n" : "") + text;
      const detectedVariables = extractVariablesFromText(newContent);
      setFormData(prev => ({
        ...prev,
        content: newContent,
        variables: detectedVariables
      }));
    } catch (error) {
      console.error("Transcription error", error);
      alert("Error en la transcripción");
    } finally {
      setIsRecording(false);
    }
  };

  // --- LOGICA OPTIMIZADA DE CARGA DE ARCHIVOS ---
  const cancelUpload = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
    }
    setIsExtracting(false);
    setUploadProgress(0);
    setUploadError("Carga cancelada por el usuario.");
    setTimeout(() => setUploadError(null), 3000);
  };

  const processFile = async (file: File) => {
    // Reset states
    setIsExtracting(true);
    setUploadProgress(0);
    setUploadError(null);
    setUploadStatus("Iniciando...");

    // Create new abort controller
    const controller = new AbortController();
    abortControllerRef.current = controller;

    try {
      // 1. Simulación de lectura del archivo (0% -> 40%)
      setUploadStatus("Leyendo archivo...");
      const fileSize = file.size;
      const chunkSize = fileSize / 10;
      let loaded = 0;

      // Simulamos la barra de progreso de lectura (rápida para local)
      const readInterval = setInterval(() => {
        if (loaded < fileSize) {
          loaded += chunkSize;
          const percentage = Math.min(40, (loaded / fileSize) * 40);
          setUploadProgress(percentage);
        } else {
          clearInterval(readInterval);
        }
      }, 50);

      // 2. Procesamiento de Gemini (40% -> 90%)
      // Usamos extractPromptFromFile pero le pasamos la señal de aborto
      setUploadStatus(`Analizando ${file.name}...`);

      // Iniciar animación de "pensando" independiente
      const thinkingInterval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev >= 90) return prev;
          return prev + (Math.random() * 5); // Incremento aleatorio
        });
      }, 300);

      const extractedData = await extractPromptFromFile(file, controller.signal);

      clearInterval(thinkingInterval);
      clearInterval(readInterval);
      setUploadProgress(100);
      setUploadStatus("Completado");

      // 3. Populate Form
      const newContent = extractedData.content || formData.content;
      const detectedVariables = extractVariablesFromText(newContent);

      setFormData(prev => ({
        ...prev,
        name: extractedData.name || prev.name,
        objective: extractedData.objective || prev.objective,
        persona: extractedData.persona || prev.persona,
        content: newContent,
        variables: detectedVariables,
        tags: extractedData.tags ? [...new Set([...prev.tags, ...extractedData.tags])] : prev.tags,
        description: `Importado de ${file.name}`
      }));

      // Delay to show 100% completion before hiding
      setTimeout(() => {
        setIsExtracting(false);
        setUploadProgress(0);
      }, 800);

    } catch (error: any) {
      if (error.message === "Operación cancelada." || error.message === "Operación cancelada por el usuario.") {
        // Handled by cancel function UI update
        return;
      }
      console.error("Error extracting file:", error);
      setUploadError(error.message || "Error desconocido al procesar el archivo.");
      setIsExtracting(false);
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
      abortControllerRef.current = null;
    }
  };
  // ------------------------------------------------

